const task = $('Extract Prompt').first().json.promptRaw

const payload = {
  model: "qwen2.5-coder:14b",
  system: "You are an expert code generator. Your ONLY output is raw file content. Never explain. Never instruct the user. Never use markdown fences. Never add commentary.",
  prompt: `TASK: ${task}

RULES:
- Output ONLY the raw file content that fulfills the TASK.
- No explanations, no "here is the code", no markdown fences.
- No preamble, no postscript, no closing remarks.
- If the TASK says to create a file with specific content, output exactly that content.
- If the TASK says to write code, output only the code.

FILE CONTENT:`,
  stream: false,
  options: {
    temperature: 0.5,
    num_ctx: 32768,
    num_predict: 8192
  }
};

return [{ json: payload }];

// The Iteration Record Keeper returns a JSON string in .response
// (it may also come back already parsed as an object — handle both)
let record = $json.response;
if (typeof record === "string") {
  record = JSON.parse(record);
}

// Build a clean, human-readable markdown record
const markdown = `TASK: ${record.task}
ITERATION_ID: ${record.iteration_id}

LOC:
${record.loc}

DESC:
${record.desc}

IMPROVEMENTS:
${record.improvements}
`;

return { json: { content: markdown } };

// Pull data from previous nodes
const taskName = $('Extract Prompt').first().json.promptRaw;
const iterationId = $itemIndex + 1;
const code = $('Coding Agent').first().json.response || "";
const improvements = "";

const payload = {
  model: "qwen2.5-coder:14b",
  system: `You are a technical record keeper. Your ONLY job is to produce a JSON object describing one iteration of a code improvement session. You MUST copy code and improvements verbatim. You MUST NOT invent, summarize, paraphrase, or alter any code. You MUST NOT fabricate improvements that were not explicitly provided. If a field is empty, you MUST use the exact fallback text given.`,
  prompt: `You are filling out one iteration record. Use ONLY the data provided below. Do NOT add information from your own knowledge.

--- TASK NAME ---
${taskName}

--- ITERATION NUMBER ---
${iterationId}

--- GENERATED CODE (copy VERBATIM, character-for-character) ---
${code}

--- IMPROVEMENTS MADE (copy VERBATIM) ---
${improvements}

--- INSTRUCTIONS ---
Output a single valid JSON object with EXACTLY these five keys:

{
  "task": "<copy TASK NAME verbatim>",
  "iteration_id": <copy ITERATION NUMBER as an integer>,
  "loc": "<copy GENERATED CODE verbatim. Do not reformat. Do not add or remove whitespace. Do not change indentation.>",
  "desc": "<one sentence, max 25 words, describing what the code actually does. Do NOT invent features not present in the code.>",
  "improvements": "<copy IMPROVEMENTS MADE verbatim. If empty, output exactly: 'Initial generation - no prior iterations'>"
}

STRICT RULES:
1. Output ONLY the JSON object. No explanations, no markdown fences, no commentary.
2. Do NOT modify the code in "loc" — copy it exactly as given.
3. Do NOT invent improvements. Only use what was provided.
4. If you are uncertain, copy text verbatim rather than paraphrasing.
5. "iteration_id" must be a number, not a string.
6. Escape all double quotes and newlines correctly inside JSON strings.

Output the JSON now:`,
  stream: false,
  format: "json",
  options: {
    temperature: 0.3,
    num_ctx: 32768,
    num_predict: 8192
  }
};

return { json: payload };

const taskName = $('Extract Prompt').first().json.promptRaw;
const iterationId = $('Is NOT First Iteration?').first().json.iteration;

const code = ($('Coding Agent').first().json.response || '')
  .replace(/```[a-zA-Z]*\n?/g, '')
  .replace(/```/g, '')
  .trim();

const improvements = $('Audit Agent (Ollama)').first().json.response || '';

const payload = {
  model: "qwen2.5-coder:14b",
  system: `You are a technical record keeper. Your ONLY job is to produce a JSON object describing one iteration of a code improvement session. You MUST copy code and improvements verbatim. You MUST NOT invent, summarize, paraphrase, or alter any code.`,
  prompt: `Output a single valid JSON object with EXACTLY these five keys.

--- TASK NAME ---
${taskName}

--- ITERATION NUMBER ---
${iterationId}

--- GENERATED CODE (copy VERBATIM) ---
${code}

--- IMPROVEMENTS MADE (copy VERBATIM) ---
${improvements || 'Initial generation - no prior iterations'}

--- OUTPUT ---
{
  "task": "<copy TASK NAME verbatim>",
  "iteration_id": <iteration number as integer>,
  "loc": "<copy GENERATED CODE verbatim>",
  "desc": "<one sentence, max 25 words>",
  "improvements": "<copy IMPROVEMENTS MADE verbatim>"
}

RULES:
1. Output ONLY the JSON object. No explanations, no fences.
2. Do not modify the code in "loc".
3. "iteration_id" must be a number, not a string.
4. Escape all double quotes and newlines correctly.

Output the JSON now:`,
  stream: false,
  format: "json",
  options: {
    temperature: 0.1,
    num_ctx: 32768,
    num_predict: 4096
  }
};

return { json: payload };

const promptRaw = $('Extract Prompt').first().json.promptRaw

return Array.from({ length: 3 }, (_, i) => ({
  json: { iteration: i + 1, promptRaw: promptRaw }
}));

const task = $('For Loop').first().json.promptRaw;
const iteration = $('Is NOT First Iteration?').first().json.iteration;

let code = '';
try { code = $('Coding Agent (Loop)').first().json.response || ''; } catch (e) {}
if (!code) {
  try { code = $('Coding Agent').first().json.response || ''; } catch (e) {}
}

code = code.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '').trim();

const chunks = ($json.chunks || []).map(c => c.content).join('\n\n');

const payload = {
  model: "qwen2.5-coder:14b",
  system: `You are a senior software engineer performing a code audit. You review the code below against the task, identify concrete flaws, and output a prioritized list of improvements. You DO NOT write code. You DO NOT ask for clarification. You output ONLY the improvement list.`,
  prompt: `TASK:
${task}

CODE TO AUDIT (iteration ${iteration}):
---BEGIN CODE---
${code}
---END CODE---

PREVIOUS ITERATION CONTEXT:
${chunks || 'None available.'}

## HARD REQUIREMENTS
- You MUST produce at least 3 suggestions unless the code meets ALL of:
  every function has a clear name, no magic values, no dead code,
  every function has a single responsibility, and the task is trivially simple (<=5 lines).
- "Code works correctly" is NOT a reason to skip suggestions.
- Do NOT suggest recursion for Fibonacci. Iteration is O(n); naive recursion is O(2^n).
- NO_IMPROVEMENTS is only valid if you also list the three criteria above as satisfied.

## BAD SUGGESTIONS (do not produce)
- "Add comments" - low value, skip it
- "Use recursion" for sequential algorithms

## GOOD SUGGESTION EXAMPLES
- Rename variable 'n3' in main() to 'next_term' for clarity.
- Extract the Fibonacci loop into a generateFibonacci(int count) method.
- Replace magic value 10 with a static final int TERM_COUNT = 10; constant.

AUDIT CHECKLIST:
- Correctness: does the code fulfill the task?
- Compute efficiency
- Naming: clear, non-abbreviated
- Modularity
- Magic values
- Error handling
- Dead code

OUTPUT FORMAT:
Numbered list. Each item: name the specific function/variable, then state what to change. One sentence per item.

If the code is correct and complete, output exactly: NO_IMPROVEMENTS

No code. No explanation. No preamble.`,
  stream: false,
  options: {
    temperature: 0.5,
    num_ctx: 32768,
    num_predict: 8192
  }
};

return [{ json: payload }];

const task = $('Extract Prompt').first().json.promptRaw;
const iteration = $('Is NOT First Iteration?').first().json.iteration;

// Audit Agent's suggestions (the numbered improvement list)
const auditSuggestions = $input.first().json.response || '';

