if (!currentCode) {
  try { currentCode = $('Coding Agent').first().json.response || ''; } catch (e) {}
}
currentCode = currentCode.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '').trim();

const payload = {
  model: "qwen2.5-coder:14b",
  system: `You are an expert code generator. Your ONLY output is the raw, complete, improved file content. You never explain, never instruct, never use markdown fences, never add commentary.`,
  prompt: `TASK:
${task}

CURRENT CODE (iteration ${iteration - 1}):
---BEGIN CODE---
${currentCode}
---END CODE---

AUDIT SUGGESTIONS TO APPLY:
${auditSuggestions}

RULES:
- Output ONLY the raw, complete file content that fulfills the TASK and applies the audit suggestions.
- Preserve the original language, structure, and functionality unless a suggestion explicitly says otherwise.
- No explanations, no "here is the code", no markdown fences, no commentary.
- No preamble, no postscript, no closing remarks.
- If a suggestion is ambiguous or would break correctness, skip it rather than guessing.
- Apply every suggestion that is concrete and unambiguous.

FILE CONTENT:`,
  stream: false,
  options: {
    temperature: 0.5,
    num_ctx: 32768,
    num_predict: 8192
  }
};

return [{ json: payload }];
